// 当前选中的账号和列表项
lv_obj_t * selected_item = NULL;
char selected_account[MAX_ACCOUNT_LENGTH] = "";
static lv_style_t style_selected;  // 选中样式

// 初始化选中样式
void init_selected_style() {
    lv_style_init(&style_selected);
    lv_style_set_bg_color(&style_selected, lv_color_hex(0x337ab7));  // 蓝色背景
    lv_style_set_text_color(&style_selected, lv_color_hex(0xffffff));  // 白色文字
}

// 列表项点击事件处理（使用 user_data 获取账号名）
void list_item_click_event(lv_event_t * e) {
    lv_obj_t * item = lv_event_get_target(e);
    const char * acc = (const char *)lv_obj_get_user_data(item);
    if (!acc) {
        // 若 user_data 为空，回退到按钮文本（但不应发生）
        acc = lv_list_get_btn_text(ui_AccountList, item);
        if (!acc) return;
    }
    
    // 清除之前选中项的样式（先确保对象有效）
    if (selected_item) {
        // 安全起见，检查 selected_item 是否仍然在列表中（尝试获取其父对象）
        // 但更可靠的方法是在列表刷新时重置 selected_item
        lv_obj_remove_style(selected_item, &style_selected, LV_PART_MAIN);
    }
    
    // 设置当前选中项样式
    selected_item = item;
    lv_obj_add_style(item, &style_selected, LV_PART_MAIN);
    
    // 安全拷贝账号名
    strncpy(selected_account, acc, MAX_ACCOUNT_LENGTH - 1);
    selected_account[MAX_ACCOUNT_LENGTH - 1] = '\0';
}

// 直接删除账号（无确认对话框）
void delete_btn_click_event(lv_event_t * e) {
    if (!selected_item || !selected_account[0]) {
        show_message_box("提示", "请先选择一个账号");
        return;
    }
    
    // 直接删除账号，不显示确认对话框
    delete_account_from_file(selected_account);
    load_accounts_to_list();
    
    // 重置选中状态（load_accounts_to_list 中已重置，此处可省略）
    selected_item = NULL;
    selected_account[0] = '\0';
    
    // 删除成功后蜂鸣器响一声
    buzzer_beep();
    
    show_message_box("成功", "账号已删除");
}

// 从文件加载账号到列表
void load_accounts_to_list() {
    // ---- 关键修复：重置选中状态，避免野指针 ----
    selected_item = NULL;
    selected_account[0] = '\0';

    // 清空列表
    if (ui_AccountList) {
        // 先释放所有按钮的 user_data
        uint32_t cnt = lv_obj_get_child_cnt(ui_AccountList);
        for (uint32_t i = 0; i < cnt; i++) {
            lv_obj_t * child = lv_obj_get_child(ui_AccountList, i);
            void * data = lv_obj_get_user_data(child);
            if (data) {
                lv_mem_free(data);
                lv_obj_set_user_data(child, NULL);
            }
        }
        lv_obj_clean(ui_AccountList);
    }
    
    // 打开账号文件
    FILE * file = fopen(FILE_PATH, "r");
    if (!file) {
        // 文件不存在或无法打开，添加空提示
        lv_obj_t *empty_text = lv_list_add_text(ui_AccountList, "暂无账号");
        lv_obj_set_style_text_font(empty_text, &ui_font_Font1, LV_PART_MAIN);
        return;
    }
    
    char line[MAX_ACCOUNT_LENGTH + MAX_PASSWORD_LENGTH + 2];
    while (fgets(line, sizeof(line), file)) {
        // 去除换行符
        line[strcspn(line, "\n")] = '\0';
        
        // 添加到列表
        lv_obj_t * item = lv_list_add_btn(ui_AccountList, NULL, line);
        // 复制账号名到 user_data（便于安全获取）
        char *acc_copy = (char *)lv_mem_alloc(strlen(line) + 1);
        if (acc_copy) {
            strcpy(acc_copy, line);
            lv_obj_set_user_data(item, acc_copy);
        }
        lv_obj_add_event_cb(item, list_item_click_event, LV_EVENT_CLICKED, NULL);
    }
    
    fclose(file);
    
    // 如果列表为空，显示提示
    if (lv_obj_get_child_cnt(ui_AccountList) == 0) {
        lv_obj_t *empty_text = lv_list_add_text(ui_AccountList, "暂无账号");
        lv_obj_set_style_text_font(empty_text, &ui_font_Font1, LV_PART_MAIN);
    }
}

// 从文件中删除账号
void delete_account_from_file(const char * account) {
    FILE * src = fopen(FILE_PATH, "r");
    FILE * temp = fopen("/spiffs/temp.txt", "w");
    
    if (!src || !temp) {
        ESP_LOGE("SPIFFS", "无法打开文件");
        if (src) fclose(src);
        if (temp) fclose(temp);
        return;
    }
    
    char line[MAX_ACCOUNT_LENGTH + MAX_PASSWORD_LENGTH + 2];
    while (fgets(line, sizeof(line), src)) {
        char existing_account[MAX_ACCOUNT_LENGTH];
        sscanf(line, "%[^,],%*s", existing_account);
        
        // 如果不是要删除的账号，则写入临时文件
        if (strcmp(existing_account, account) != 0) {
            fputs(line, temp);
        }
    }
    
    fclose(src);
    fclose(temp);
    
    // 删除原文件并将临时文件重命名
    remove(FILE_PATH);
    rename("/spiffs/temp.txt", FILE_PATH);

    delete_save_account("acc");
    delete_save_account("pwd");
}

// 退出按钮事件
void ui_event_exitbtu2(lv_event_t * e) {
    lv_event_code_t event_code = lv_event_get_code(e);

    if(event_code == LV_EVENT_CLICKED) {
        char account[MAX_ACCOUNT_LENGTH] = {0};
        char password[MAX_PASSWORD_LENGTH] = {0};
        if(read_text_from_nvs(account, MAX_ACCOUNT_LENGTH, "acc") == ESP_OK)
        {
            if(read_text_from_nvs(password, MAX_PASSWORD_LENGTH, "pwd") == ESP_OK)
            {
                lv_textarea_set_text(ui_zhanghao, account);
                lv_textarea_set_text(ui_mima, password);
                lv_obj_add_state(ui_jizhu, LV_STATE_CHECKED); 
            }
        }
        _ui_screen_change(&ui_Screen1, LV_SCR_LOAD_ANIM_FADE_ON, 200, 0, &ui_Screen1_screen_init);
    }
}

